create or replace function public.marcar_publicacao_repetida() returns trigger language plpgsql set search_path to '' as $function$ begin if new.origem <> 'djen' or new.data_disponibilizacao is null then return new; end if; select exists ( select 1 from public.intimacoes i where i.origem = 'djen' and i.numero_processo_normalizado = upper(regexp_replace(new.numero_processo, '[^0-9A-Za-z]', '', 'g')) and i.data_disponibilizacao = new.data_disponibilizacao and coalesce(i.tipo_documento, '') = coalesce(new.tipo_documento, '') ) into new.repetida; return new; end; $function$